package com.procurement.purchaseorder.entity;import com.procurement.costcenter.entity.CostCenter;import com.procurement.department.entity.Department;import com.procurement.purchaserequest.entity.PurchaseRequest;import com.procurement.quotationcomparison.entity.QuotationComparison;import com.procurement.vendor.entity.Vendor;import com.procurement.vendorquotation.entity.VendorQuotation;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;@Entity@Table(name="purchase_orders",uniqueConstraints={@UniqueConstraint(columnNames="po_number"),@UniqueConstraint(columnNames="quotation_comparison_id")})@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class PurchaseOrder{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="purchase_order_id")private Long id;@Column(name="po_number",nullable=false,length=40)private String poNumber;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="quotation_comparison_id",nullable=false,unique=true)private QuotationComparison quotationComparison;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_quotation_id",nullable=false)private VendorQuotation vendorQuotation;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_id",nullable=false)private Vendor vendor;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_request_id",nullable=false)private PurchaseRequest purchaseRequest;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="department_id",nullable=false)private Department department;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="cost_center_id",nullable=false)private CostCenter costCenter;@Column(name="order_date",nullable=false)private LocalDate orderDate;@Column(name="expected_delivery_date",nullable=false)private LocalDate expectedDeliveryDate;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal subtotal=BigDecimal.ZERO;@Column(name="discount_amount",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal discountAmount=BigDecimal.ZERO;@Column(name="tax_amount",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal taxAmount=BigDecimal.ZERO;@Column(name="shipping_charges",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal shippingCharges=BigDecimal.ZERO;@Column(name="other_charges",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal otherCharges=BigDecimal.ZERO;@Column(name="grand_total",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal grandTotal=BigDecimal.ZERO;@Column(name="payment_terms",length=200)private String paymentTerms;@Column(name="delivery_address",length=500)private String deliveryAddress;@Column(name="billing_address",length=500)private String billingAddress;@Column(length=1000)private String remarks;@Enumerated(EnumType.STRING)@Column(nullable=false,length=25)private PurchaseOrderStatus status;@Column(name="created_by",nullable=false)private String createdBy;@Column(name="updated_by")private String updatedBy;@Column(name="created_at",updatable=false)private LocalDateTime createdAt;@Column(name="updated_at")private LocalDateTime updatedAt;@PrePersist void pre(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=PurchaseOrderStatus.GENERATED;}@PreUpdate void upd(){updatedAt=LocalDateTime.now();}}
